 "type": "hazard",
 "summary": "build_search_index.py fails with \"unexpected token in shard-*.json\" when cached shards have an old tokenizer version; fix with --clear-cache",
 "content": "Command: python scripts/build_search_index.py. Symptom: \"index build failed: unexpected token in shard-000.json\" (exit 1). Cause: not a parse error; var/cache/search/*.json shards were written with an older TOKENIZER version (shard had tokenizer 2, script expects 3). Fix: rerun with `--clear-cache`, which deletes the cached shards (regenerable) and rebuilds var/search/index.json. Rerun with --clear-cache whenever TOKENIZER is bumped.",
 "tags": [
  "search-index",
  "scripts",
  "cache"
 ],
 "physical": [
  "scripts/build_search_index.py"
 ],
 "invalidated_by": [
  "scripts/build_search_index.py"
 ]
}
